我现在一次性取回所需的确切页面文本，只打印有界上下文窗口供核实。

```python
import json, re
pages = {}
for a,b in [(1,2),(4,5),(10,11),(22,23),(46,47),(50,52)]:
    res = run_command(['python','read_pdf.py','--start-page',str(a),'--end-page',str(b)])
    if res['rc'] != 0:
        print('ERR', a, b, res['stderr'][:150]); continue
    d = json.loads(res['stdout'])
    for pg in d['pages']:
        pages[pg['page']] = pg['text']
def norm(t):
    return re.sub(r'\s+',' ',t).strip()
NP = {k: norm(v) for k,v in pages.items()}
print('pages loaded:', sorted(NP))
pats = {'cat':'interacting','search':'snowball','sc':'majority voting','tot':'Tree of Thought','tools':'16,464','camel':'inception','gen':'human evaluators','t4':'Table 4','found':'self-verification'}
for k,pat in pats.items():
    for pg in sorted(NP):
        i = NP[pg].find(pat)
        if i >= 0:
            print('=== %s | page %d ===' % (k, pg))
            print(NP[pg][max(0,i-200):i+450])
            break
